// The agent is told to return bare JSON; strip code fences or stray text defensively.
const raw = String($input.first().json.output ?? '').trim();
const unfenced = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const start = unfenced.indexOf('{');
const end = unfenced.lastIndexOf('}');
try {
  return [{ json: JSON.parse(unfenced.slice(start, end + 1)) }];
} catch (error) {
  return [{ json: { error: 'agent_output_not_json', raw } }];
}
